import{_ as a,o as n,c as s,l as e,t as i,a as t,N as o}from"./chunks/framework.CMqbtke2.js";const v=JSON.parse('{"title":"gitprotocol-http | x-cmd man (git man5) | Git HTTP-based protocols","titleTemplate":false,"description":"x-cmd man (git man5 Manual Page) | gitprotocol-http - Git HTTP-based protocols","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"gitprotocol-http | x-cmd man (git man5) | Git HTTP-based protocols"}],["meta",{"name":"og:description","content":"x-cmd man (git man5 Manual Page) | gitprotocol-http - Git HTTP-based protocols"}]]},"headers":[],"params":{"isMan":true,"man":"gitprotocol-http","category":"git man5","desc":"Git HTTP-based protocols"},"relativePath":"git/man5/gitprotocol-http.md","filePath":"git/man5/gitprotocol-http.md"}'),c={name:"git/man5/gitprotocol-http.md"},p={class:"visually-hidden"},d=o(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>gitprotocol-http - Git HTTP-based protocols</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">over-the-wire-protocol</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Git supports two HTTP based transfer protocols. A &quot;dumb&quot; protocol which requires only a standard HTTP server on the server end of the connection, and a &quot;smart&quot; protocol which requires a Git aware CGI (or server module). This document describes both protocols.</p><p>As a design feature smart clients can automatically upgrade &quot;dumb&quot; protocol URLs to smart URLs. This permits all users to have the same published URL, and the peers automatically select the most efficient transport available to them.</p><h2 id="url-format" tabindex="-1">URL FORMAT <a class="header-anchor" href="#url-format" aria-label="Permalink to &quot;URL FORMAT&quot;">​</a></h2><p>URLs for Git repositories accessed by HTTP use the standard HTTP URL syntax documented by RFC 1738, so they are of the form:</p><blockquote><pre><code>http://&lt;host&gt;:&lt;port&gt;/&lt;path&gt;?&lt;searchpart&gt;
</code></pre></blockquote><p>Within this documentation the placeholder <strong>$GIT_URL</strong> will stand for the http:// repository URL entered by the end-user.</p><p>Servers SHOULD handle all requests to locations matching <strong>$GIT_URL</strong>, as both the &quot;smart&quot; and &quot;dumb&quot; HTTP protocols used by Git operate by appending additional path components onto the end of the user supplied <strong>$GIT_URL</strong> string.</p><p>An example of a dumb client requesting for a loose object:</p><blockquote><pre><code>$GIT_URL:     http://example.com:8080/git/repo.git
URL request:  http://example.com:8080/git/repo.git/objects/d0/49f6c27a2244e12041955e262a404c7faba355
</code></pre></blockquote><p>An example of a smart request to a catch-all gateway:</p><blockquote><pre><code>$GIT_URL:     http://example.com/daemon.cgi?svc=git&amp;q=
URL request:  http://example.com/daemon.cgi?svc=git&amp;q=/info/refs&amp;service=git-receive-pack
</code></pre></blockquote><p>An example of a request to a submodule:</p><blockquote><pre><code>$GIT_URL:     http://example.com/git/repo.git/path/submodule.git
URL request:  http://example.com/git/repo.git/path/submodule.git/info/refs
</code></pre></blockquote><p>Clients MUST strip a trailing <strong>/</strong>, if present, from the user supplied <strong>$GIT_URL</strong> string to prevent empty path tokens (<strong>//</strong>) from appearing in any URL sent to a server. Compatible clients MUST expand <strong>$GIT_URL/info/refs</strong> as <strong>foo/info/refs</strong> and not <strong>foo//info/refs</strong>.</p><h2 id="authentication" tabindex="-1">AUTHENTICATION <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;AUTHENTICATION&quot;">​</a></h2><p>Standard HTTP authentication is used if authentication is required to access a repository, and MAY be configured and enforced by the HTTP server software.</p><p>Because Git repositories are accessed by standard path components server administrators MAY use directory based permissions within their HTTP server to control repository access.</p><p>Clients SHOULD support Basic authentication as described by RFC 2617. Servers SHOULD support Basic authentication by relying upon the HTTP server placed in front of the Git server software.</p><p>Servers SHOULD NOT require HTTP cookies for the purposes of authentication or access control.</p><p>Clients and servers MAY support other common forms of HTTP based authentication, such as Digest authentication.</p><h2 id="ssl" tabindex="-1">SSL <a class="header-anchor" href="#ssl" aria-label="Permalink to &quot;SSL&quot;">​</a></h2><p>Clients and servers SHOULD support SSL, particularly to protect passwords when relying on Basic HTTP authentication.</p><h2 id="session-state" tabindex="-1">SESSION STATE <a class="header-anchor" href="#session-state" aria-label="Permalink to &quot;SESSION STATE&quot;">​</a></h2><p>The Git over HTTP protocol (much like HTTP itself) is stateless from the perspective of the HTTP server side. All state MUST be retained and managed by the client process. This permits simple round-robin load-balancing on the server side, without needing to worry about state management.</p><p>Clients MUST NOT require state management on the server side in order to function correctly.</p><p>Servers MUST NOT require HTTP cookies in order to function correctly. Clients MAY store and forward HTTP cookies during request processing as described by RFC 2616 (HTTP/1.1). Servers SHOULD ignore any cookies sent by a client.</p><h2 id="general-request-processing" tabindex="-1">GENERAL REQUEST PROCESSING <a class="header-anchor" href="#general-request-processing" aria-label="Permalink to &quot;GENERAL REQUEST PROCESSING&quot;">​</a></h2><p>Except where noted, all standard HTTP behavior SHOULD be assumed by both client and server. This includes (but is not necessarily limited to):</p><p>If there is no repository at <strong>$GIT_URL</strong>, or the resource pointed to by a location matching <strong>$GIT_URL</strong> does not exist, the server MUST NOT respond with <strong>200 OK</strong> response. A server SHOULD respond with <strong>404 Not Found</strong>, <strong>410 Gone</strong>, or any other suitable HTTP status code which does not imply the resource exists as requested.</p><p>If there is a repository at <strong>$GIT_URL</strong>, but access is not currently permitted, the server MUST respond with the <strong>403 Forbidden</strong> HTTP status code.</p><p>Servers SHOULD support both HTTP 1.0 and HTTP 1.1. Servers SHOULD support chunked encoding for both request and response bodies.</p><p>Clients SHOULD support both HTTP 1.0 and HTTP 1.1. Clients SHOULD support chunked encoding for both request and response bodies.</p><p>Servers MAY return ETag and/or Last-Modified headers.</p><p>Clients MAY revalidate cached entities by including If-Modified-Since and/or If-None-Match request headers.</p><p>Servers MAY return <strong>304 Not Modified</strong> if the relevant headers appear in the request and the entity has not changed. Clients MUST treat <strong>304 Not Modified</strong> identical to <strong>200 OK</strong> by reusing the cached entity.</p><p>Clients MAY reuse a cached entity without revalidation if the Cache-Control and/or Expires header permits caching. Clients and servers MUST follow RFC 2616 for cache controls.</p><h2 id="discovering-references" tabindex="-1">DISCOVERING REFERENCES <a class="header-anchor" href="#discovering-references" aria-label="Permalink to &quot;DISCOVERING REFERENCES&quot;">​</a></h2><p>All HTTP clients MUST begin either a fetch or a push exchange by discovering the references available on the remote repository.</p><h3 id="dumb-clients" tabindex="-1">Dumb Clients <a class="header-anchor" href="#dumb-clients" aria-label="Permalink to &quot;Dumb Clients&quot;">​</a></h3><p>HTTP clients that only support the &quot;dumb&quot; protocol MUST discover references by making a request for the special info/refs file of the repository.</p><p>Dumb HTTP clients MUST make a <strong>GET</strong> request to <strong>$GIT_URL/info/refs</strong>, without any search/query parameters.</p><blockquote><pre><code>C: GET $GIT_URL/info/refs HTTP/1.0
</code></pre></blockquote><blockquote><pre><code>S: 200 OK
S:
S: 95dcfa3633004da0049d3d0fa03f80589cbcaf31	refs/heads/maint
S: d049f6c27a2244e12041955e262a404c7faba355	refs/heads/master
S: 2cb58b79488a98d2721cea644875a8dd0026b115	refs/tags/v1.0
S: a3c2e2402b99163d1d59756e5f207ae21cccba4c	refs/tags/v1.0^{}
</code></pre></blockquote><p>The Content-Type of the returned info/refs entity SHOULD be <strong>text/plain; charset=utf-8</strong>, but MAY be any content type. Clients MUST NOT attempt to validate the returned Content-Type. Dumb servers MUST NOT return a return type starting with <strong>application/x-git-</strong>.</p><p>Cache-Control headers MAY be returned to disable caching of the returned entity.</p><p>When examining the response clients SHOULD only examine the HTTP status code. Valid responses are <strong>200 OK</strong>, or <strong>304 Not Modified</strong>.</p><p>The returned content is a UNIX formatted text file describing each ref and its known value. The file SHOULD be sorted by name according to the C locale ordering. The file SHOULD NOT include the default ref named <strong>HEAD</strong>.</p><blockquote><pre><code>info_refs   =  *( ref_record )
ref_record  =  any_ref / peeled_ref
</code></pre></blockquote><blockquote><pre><code>any_ref     =  obj-id HTAB refname LF
peeled_ref  =  obj-id HTAB refname LF
 obj-id HTAB refname &quot;^{}&quot; LF
</code></pre></blockquote><h3 id="smart-clients" tabindex="-1">Smart Clients <a class="header-anchor" href="#smart-clients" aria-label="Permalink to &quot;Smart Clients&quot;">​</a></h3><p>HTTP clients that support the &quot;smart&quot; protocol (or both the &quot;smart&quot; and &quot;dumb&quot; protocols) MUST discover references by making a parameterized request for the info/refs file of the repository.</p><p>The request MUST contain exactly one query parameter, <strong>service=$servicename</strong>, where <strong>$servicename</strong> MUST be the service name the client wishes to contact to complete the operation. The request MUST NOT contain additional query parameters.</p><blockquote><pre><code>C: GET $GIT_URL/info/refs?service=git-upload-pack HTTP/1.0
</code></pre></blockquote><p>dumb server reply:</p><blockquote><pre><code>S: 200 OK
S:
S: 95dcfa3633004da0049d3d0fa03f80589cbcaf31	refs/heads/maint
S: d049f6c27a2244e12041955e262a404c7faba355	refs/heads/master
S: 2cb58b79488a98d2721cea644875a8dd0026b115	refs/tags/v1.0
S: a3c2e2402b99163d1d59756e5f207ae21cccba4c	refs/tags/v1.0^{}
</code></pre></blockquote><p>smart server reply:</p><blockquote><pre><code>S: 200 OK
S: Content-Type: application/x-git-upload-pack-advertisement
S: Cache-Control: no-cache
S:
S: 001e# service=git-upload-pack\\n
S: 0000
S: 004895dcfa3633004da0049d3d0fa03f80589cbcaf31 refs/heads/maint\\0multi_ack\\n
S: 003fd049f6c27a2244e12041955e262a404c7faba355 refs/heads/master\\n
S: 003c2cb58b79488a98d2721cea644875a8dd0026b115 refs/tags/v1.0\\n
S: 003fa3c2e2402b99163d1d59756e5f207ae21cccba4c refs/tags/v1.0^{}\\n
S: 0000
</code></pre></blockquote><p>The client may send Extra Parameters (see <strong>gitprotocol-pack</strong>(5)) as a colon-separated string in the Git-Protocol HTTP header.</p><p>Uses the <strong>--http-backend-info-refs</strong> option to <strong>git-upload-pack</strong>(1).</p><br>`,65),l=e("blockquote",null,[e("p",null,"Dumb servers MUST respond with the dumb server reply format."),e("p",null,"See the prior section under dumb clients for a more detailed description of the dumb server response.")],-1),h=e("br",null,null,-1),u=o(`<blockquote><p>If the server does not recognize the requested service name, or the requested service name has been disabled by the server administrator, the server MUST respond with the <strong>403 Forbidden</strong> HTTP status code.</p><p>Otherwise, smart servers MUST respond with the smart server reply format for the requested service name.</p><p>Cache-Control headers SHOULD be used to disable caching of the returned entity.</p><p>The Content-Type MUST be <strong>application/x-$servicename-advertisement</strong>. Clients SHOULD fall back to the dumb protocol if another content type is returned. When falling back to the dumb protocol clients SHOULD NOT make an additional request to <strong>$GIT_URL/info/refs</strong>, but instead SHOULD use the response already in hand. Clients MUST NOT continue if they do not support the dumb protocol.</p><p>Clients MUST validate the status code is either <strong>200 OK</strong> or <strong>304 Not Modified</strong>.</p><p>Clients MUST validate the first five bytes of the response entity matches the regex <strong>^[0-9a-f]{4}#</strong>. If this test fails, clients MUST NOT continue.</p><p>Clients MUST parse the entire response as a sequence of pkt-line records.</p><p>Clients MUST verify the first pkt-line is <strong># service=$servicename</strong>. Servers MUST set $servicename to be the request parameter value. Servers SHOULD include an LF at the end of this line. Clients MUST ignore an LF at the end of the line.</p><p>Servers MUST terminate the response with the magic <strong>0000</strong> end pkt-line marker.</p><p>The returned response is a pkt-line stream describing each ref and its known value. The stream SHOULD be sorted by name according to the C locale ordering. The stream SHOULD include the default ref named <strong>HEAD</strong> as the first ref. The stream MUST include capability declarations behind a NUL on the first ref.</p><p>The returned response contains &quot;version 1&quot; if &quot;version=1&quot; was sent as an Extra Parameter.</p><blockquote><pre><code>smart_reply     =  PKT-LINE(&quot;# service=$servicename&quot; LF)
     &quot;0000&quot;
     *1(&quot;version 1&quot;)
     ref_list
     &quot;0000&quot;
ref_list        =  empty_list / non_empty_list
</code></pre></blockquote><blockquote><pre><code>empty_list      =  PKT-LINE(zero-id SP &quot;capabilities^{}&quot; NUL cap-list LF)
</code></pre></blockquote><blockquote><pre><code>non_empty_list  =  PKT-LINE(obj-id SP name NUL cap_list LF)
     *ref_record
</code></pre></blockquote><blockquote><pre><code>cap-list        =  capability *(SP capability)
capability      =  1*(LC_ALPHA / DIGIT / &quot;-&quot; / &quot;_&quot;)
LC_ALPHA        =  %x61-7A
</code></pre></blockquote><blockquote><pre><code>ref_record      =  any_ref / peeled_ref
any_ref         =  PKT-LINE(obj-id SP name LF)
peeled_ref      =  PKT-LINE(obj-id SP name LF)
     PKT-LINE(obj-id SP name &quot;^{}&quot; LF
</code></pre></blockquote></blockquote><h2 id="smart-service-git-upload-pack" tabindex="-1">SMART SERVICE GIT-UPLOAD-PACK <a class="header-anchor" href="#smart-service-git-upload-pack" aria-label="Permalink to &quot;SMART SERVICE GIT-UPLOAD-PACK&quot;">​</a></h2><p>This service reads from the repository pointed to by <strong>$GIT_URL</strong>.</p><p>Clients MUST first perform ref discovery with <strong>$GIT_URL/info/refs?service=git-upload-pack</strong>.</p><blockquote><pre><code>C: POST $GIT_URL/git-upload-pack HTTP/1.0
C: Content-Type: application/x-git-upload-pack-request
C:
C: 0032want 0a53e9ddeaddad63ad106860237bbf53411d11a7\\n
C: 0032have 441b40d833fdfa93eb2908e52742248faf0ee993\\n
C: 0000
</code></pre></blockquote><blockquote><pre><code>S: 200 OK
S: Content-Type: application/x-git-upload-pack-result
S: Cache-Control: no-cache
S:
S: ....ACK %s, continue
S: ....NAK
</code></pre></blockquote><p>Clients MUST NOT reuse or revalidate a cached response. Servers MUST include sufficient Cache-Control headers to prevent caching of the response.</p><p>Servers SHOULD support all capabilities defined here.</p><p>Clients MUST send at least one &quot;want&quot; command in the request body. Clients MUST NOT reference an id in a &quot;want&quot; command which did not appear in the response obtained through ref discovery unless the server advertises capability <strong>allow-tip-sha1-in-want</strong> or <strong>allow-reachable-sha1-in-want</strong>.</p><blockquote><pre><code>compute_request   =  want_list
       have_list
       request_end
request_end       =  &quot;0000&quot; / &quot;done&quot;
</code></pre></blockquote><blockquote><pre><code>want_list         =  PKT-LINE(want SP cap_list LF)
       *(want_pkt)
want_pkt          =  PKT-LINE(want LF)
want              =  &quot;want&quot; SP id
cap_list          =  capability *(SP capability)
</code></pre></blockquote><blockquote><pre><code>have_list         =  *PKT-LINE(&quot;have&quot; SP id LF)
</code></pre></blockquote><p>TODO: Document this further.</p><h3 id="the-negotiation-algorithm" tabindex="-1">The Negotiation Algorithm <a class="header-anchor" href="#the-negotiation-algorithm" aria-label="Permalink to &quot;The Negotiation Algorithm&quot;">​</a></h3><p>The computation to select the minimal pack proceeds as follows (C = client, S = server):</p><p><em>init step:</em></p><p>C: Use ref discovery to obtain the advertised refs.</p><p>C: Place any object seen into set <strong>advertised</strong>.</p><p>C: Build an empty set, <strong>common</strong>, to hold the objects that are later determined to be on both ends.</p><p>C: Build a set, <strong>want</strong>, of the objects from <strong>advertised</strong> the client wants to fetch, based on what it saw during ref discovery.</p><p>C: Start a queue, <strong>c_pending</strong>, ordered by commit time (popping newest first). Add all client refs. When a commit is popped from the queue its parents SHOULD be automatically inserted back. Commits MUST only enter the queue once.</p><p><em>one compute step:</em></p><p>C: Send one <strong>$GIT_URL/git-upload-pack</strong> request:</p><blockquote><pre><code>C: 0032want &lt;want #1&gt;...............................
C: 0032want &lt;want #2&gt;...............................
....
C: 0032have &lt;common #1&gt;.............................
C: 0032have &lt;common #2&gt;.............................
....
C: 0032have &lt;have #1&gt;...............................
C: 0032have &lt;have #2&gt;...............................
....
C: 0000
</code></pre></blockquote><p>The stream is organized into &quot;commands&quot;, with each command appearing by itself in a pkt-line. Within a command line, the text leading up to the first space is the command name, and the remainder of the line to the first LF is the value. Command lines are terminated with an LF as the last byte of the pkt-line value.</p><p>Commands MUST appear in the following order, if they appear at all in the request stream:</p><blockquote><p>·</p><p>&quot;want&quot;</p></blockquote><blockquote><p>·</p><p>&quot;have&quot;</p></blockquote><p>The stream is terminated by a pkt-line flush (<strong>0000</strong>).</p><p>A single &quot;want&quot; or &quot;have&quot; command MUST have one hex formatted object name as its value. Multiple object names MUST be sent by sending multiple commands. Object names MUST be given using the object format negotiated through the <strong>object-format</strong> capability (default SHA-1).</p><p>The <strong>have</strong> list is created by popping the first 32 commits from <strong>c_pending</strong>. Less can be supplied if <strong>c_pending</strong> empties.</p><p>If the client has sent 256 &quot;have&quot; commits and has not yet received one of those back from <strong>s_common</strong>, or the client has emptied <strong>c_pending</strong> it SHOULD include a &quot;done&quot; command to let the server know it won&#39;t proceed:</p><blockquote><pre><code>C: 0009done
</code></pre></blockquote><p>S: Parse the git-upload-pack request:</p><p>Verify all objects in <strong>want</strong> are directly reachable from refs.</p><p>The server MAY walk backwards through history or through the reflog to permit slightly stale requests.</p><p>If no &quot;want&quot; objects are received, send an error: TODO: Define error if no &quot;want&quot; lines are requested.</p><p>If any &quot;want&quot; object is not reachable, send an error: TODO: Define error if an invalid &quot;want&quot; is requested.</p><p>Create an empty list, <strong>s_common</strong>.</p><p>If &quot;have&quot; was sent:</p><p>Loop through the objects in the order supplied by the client.</p><p>For each object, if the server has the object reachable from a ref, add it to <strong>s_common</strong>. If a commit is added to <strong>s_common</strong>, do not add any ancestors, even if they also appear in <strong>have</strong>.</p><p>S: Send the git-upload-pack response:</p><p>If the server has found a closed set of objects to pack or the request ends with &quot;done&quot;, it replies with the pack. TODO: Document the pack based response</p><blockquote><pre><code>S: PACK...
</code></pre></blockquote><p>The returned stream is the side-band-64k protocol supported by the git-upload-pack service, and the pack is embedded into stream 1. Progress messages from the server side MAY appear in stream 2.</p><p>Here a &quot;closed set of objects&quot; is defined to have at least one path from every &quot;want&quot; to at least one &quot;common&quot; object.</p><p>If the server needs more information, it replies with a status continue response: TODO: Document the non-pack response</p><p>C: Parse the upload-pack response: TODO: Document parsing response</p><p><em>Do another compute step.</em></p><h2 id="smart-service-git-receive-pack" tabindex="-1">SMART SERVICE GIT-RECEIVE-PACK <a class="header-anchor" href="#smart-service-git-receive-pack" aria-label="Permalink to &quot;SMART SERVICE GIT-RECEIVE-PACK&quot;">​</a></h2><p>This service reads from the repository pointed to by <strong>$GIT_URL</strong>.</p><p>Clients MUST first perform ref discovery with <strong>$GIT_URL/info/refs?service=git-receive-pack</strong>.</p><blockquote><pre><code>C: POST $GIT_URL/git-receive-pack HTTP/1.0
C: Content-Type: application/x-git-receive-pack-request
C:
C: ....0a53e9ddeaddad63ad106860237bbf53411d11a7 441b40d833fdfa93eb2908e52742248faf0ee993 refs/heads/maint\\0 report-status
C: 0000
C: PACK....
</code></pre></blockquote><blockquote><pre><code>S: 200 OK
S: Content-Type: application/x-git-receive-pack-result
S: Cache-Control: no-cache
S:
S: ....
</code></pre></blockquote><p>Clients MUST NOT reuse or revalidate a cached response. Servers MUST include sufficient Cache-Control headers to prevent caching of the response.</p><p>Servers SHOULD support all capabilities defined here.</p><p>Clients MUST send at least one command in the request body. Within the command portion of the request body clients SHOULD send the id obtained through ref discovery as old_id.</p><blockquote><pre><code>update_request  =  command_list
     &quot;PACK&quot; &lt;binary data&gt;
</code></pre></blockquote><blockquote><pre><code>command_list    =  PKT-LINE(command NUL cap_list LF)
     *(command_pkt)
command_pkt     =  PKT-LINE(command LF)
cap_list        =  *(SP capability) SP
</code></pre></blockquote><blockquote><pre><code>command         =  create / delete / update
create          =  zero-id SP new_id SP name
delete          =  old_id SP zero-id SP name
update          =  old_id SP new_id SP name
</code></pre></blockquote><p>TODO: Document this further.</p><h2 id="references" tabindex="-1">REFERENCES <a class="header-anchor" href="#references" aria-label="Permalink to &quot;REFERENCES&quot;">​</a></h2><p><strong>RFC 1738: Uniform Resource Locators (URL)</strong>[1] <strong>RFC 2616: Hypertext Transfer Protocol --- HTTP/1.1</strong>[2]</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>gitprotocol-pack</strong>(5) <strong>gitprotocol-capabilities</strong>(5)</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><ol><li></li></ol><p>: RFC 1738: Uniform Resource Locators (URL)</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">http://www.ietf.org/rfc/rfc1738.txt</span></span></code></pre></div><ol start="2"><li></li></ol><p>: RFC 2616: Hypertext Transfer Protocol --- HTTP/1.1</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">http://www.ietf.org/rfc/rfc2616.txt</span></span></code></pre></div>`,75);function m(r,g,b,f,T,q){return n(),s("div",null,[e("h1",p,i(r.$params.man),1),d,t(" **Dumb Server Response** "),l,h,t(" **Smart Server Response** "),u])}const k=a(c,[["render",m]]);export{v as __pageData,k as default};
